from collections import Counter
def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    out=[]
    for r in g:
        row=[]
        for c,v in enumerate(r):
            if v==bg: row.append(bg)
            else:
                # count cells ==v that have same-valued neighbors (border)
                nb=sum(1 for dr,dc in[(1,0),(-1,0),(0,1),(0,-1)] if 0<=r+dr<H and 0<=c+dc<W and g[r+dr][c+dc]==v)
                if nb>=2: row.append(v)
                elif v==2: row.append(8)
                else: row.append(v)
        out.append(row)
    return out
