def f(g):
    # find each rectangle (closed region) of 2-border, fill interior with a color that is not 0 or 2.
    # Use a distinct color per rectangle; demo 1 uses 8, demo 2 uses 4, demo 3 uses both 3 and 8 for two rectangles.
    H,W=len(g),len(g[0])
    out=[r[:] for r in g]
    from collections import deque
    seen=[[False]*W for _ in range(H)]
    rects=[]
    for ri in range(H):
        for ci in range(W):
            if g[ri][ci]==2 and not seen[ri][ci]:
                stack=[(ri,ci)]; seen[ri][ci]=True; cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and g[nr][nc]==2:
                            seen[nr][nc]=True; stack.append((nr,nc))
                rects.append(cells)
    nextc=3
    for cells in rects:
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        # verify closed: border fully 2
        if all(0<r0-r or r>r1-c for r in (r0,r1)) and True:
            pass
        # flood from outside to mark boundary
        bf=[[False]*W for _ in range(H)]; q=deque()
        for r in range(H):
            for c in (0,W-1):
                if g[r][c]!=2 and not bf[r][c]: bf[r][c]=True; q.append((r,c))
        for c in range(W):
            for r in (0,H-1):
                if g[r][c]!=2 and not bf[r][c]: bf[r][c]=True; q.append((r,c))
        while q:
            r,c=q.popleft()
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and g[nr][nc]!=2 and not bf[nr][nc]:
                    bf[nr][nc]=True; q.append((nr,nc))
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if not bf[r][c] and g[r][c]==0:
                    out[r][c]=nextc
        nextc+=1
    return out
