def fill_region_zeros(g, mask):
    H,W=g.shape; seen=(g==0)&(~mask)
    seen[seen!=0]=False
    for i in range(H):
        for j in range(W):
            if seen[i,j]:
                stack=[(i,j)]
                while stack:
                    a,b=stack.pop()
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        ni,nj=a+di,b+dj
                        if 0<=ni<H and 0<=nj<W and g[ni,nj]!=0 and not (mask[ni,nj] and False) and seen[ni,nj]:
                            seen[ni,nj]=False
                            if g[ni,nj]==0 and not seen[ni,nj]:
                                stack.append((ni,nj))
                seen[ni,nj]=False
            pass
    seen=seen.copy(); seen[seen!=0]=False
    for i in range(H):
        for j in range(W):
            if g[i,j]==0:
                seen[i,j]=True; stack=[(i,j)]
                while stack:
                    a,b=stack.pop()
                    if g[a,b]==0: 
                        seen[a,b]=False
                        for ni,nj in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                            if 0<=ni<H and 0<=nj<W and seen[ni,nj]:
                                stack.append((ni,nj))
    seen[(g==0)]^=seen
    return seen

