import numpy as np
def f(g):
    g=[r[:] for r in g]; out=[r[:] for r in g]; H,W=len(g),len(g[0])
    seen=set(); noise=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==2 and (i,j) not in seen:
                stack=[(i,j)];S={(i,j)};cells=[]
                while stack:
                    a,b=stack.pop();cells.append((a,b))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            x,y=a+dy,b+dx
                            if 0<=x<H and 0<=y<W and g[x][y]==2 and (x,y) not in S:
                                S.add((x,y));stack.append((x,y))
                seen|=S
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                # complete rectangle border of 2s
                ok=all(g[x][y]==2 for x in range(r0,r1+1) for y in range(c0,c1+1)
                       if x in(r0,r1) or y in(c0,c1))
                if not ok:
                    noise.append((r0,c0,r1,c1,cells))
                    continue
                fh=8 if (r1-r0-1)*(c1-c0-1)<=10 else 4
                for x in range(r0+1,r1):
                    for y in range(c0+1,c1):
                        if g[x][y]!=2:
                            out[x][y]=fh
    for r0,c0,r1,c1,cells in noise:
        out[r0][c0]=0
    return out
